
const LEADING_COMMANDS = [
  'turn it into',
  'i would like',
  'make it more',
  'make it',
  'make the',
  'make',
  'turn it',
  'turn the',
  'turn',
  'can you',
  'could you',
  'please',
  'i want',
  "i'd like",
  "let's",
  'lets',
  'give it',
  'give the',
  'give',
  'add a',
  'add an',
  'add',
  'create a',
  'create an',
  'create',
  'build a',
  'build an',
  'build',
  'change the',
  'change',
  'update the',
  'update',
  'redesign the',
  'redesign',
  'improve the',
  'improve',
  'refactor the',
  'refactor',
  'tweak the',
  'tweak',
  'adjust the',
  'adjust',
  'set the',
  'set',
  'rework the',
  'rework',
];

const CONJUNCTIONS = new Set([
  'and',
  'or',
  'but',
  'then',
  'plus',
  'with',
  'while',
  'so',
]);

const FILLER = new Set([
  'it',
  'its',
  "it's",
  'the',
  'a',
  'an',
  'more',
  'less',
  'very',
  'really',
  'much',
  'bit',
  'little',
  'some',
  'this',
  'that',
  'into',
  'for',
  'of',
  'on',
  'to',
  'be',
  'is',
  'look',
  'looks',
  'feel',
  'feels',
  'way',
  'overall',
  'all',
]);

export const RUN_LABEL_MAX_LENGTH = 24;
export const RUN_LABEL_MAX_WORDS = 3;

const titleCase = (words: string[]): string => {
  const titledWords = words.map((word) =>
    word ? word[0].toUpperCase() + word.slice(1) : word,
  );
  const fittingWords = titledWords.reduce<string[]>((selected, word) => {
    const candidate = [...selected, word].join(' ');
    return candidate.length <= RUN_LABEL_MAX_LENGTH
      ? [...selected, word]
      : selected;
  }, []);
  return fittingWords.join(' ') || titledWords[0] || '';
};

export function deriveRunLabel(prompt: string): string {
  const raw = (prompt ?? '').trim();
  if (!raw) return 'Variants';
  let text = raw.toLowerCase().replace(/[`*_#>~"]/g, ' ');

  for (const cmd of LEADING_COMMANDS) {
    if (text.startsWith(cmd + ' ')) {
      text = text.slice(cmd.length).trim();
      break;
    }
  }

  const tokens: string[] = [];
  for (const tok of text.split(/[\s,;./]+/)) {
    const w = tok.replace(/[^a-z0-9-]/g, '');
    if (!w) continue;
    if (CONJUNCTIONS.has(w)) break;
    tokens.push(w);
  }

  const content = tokens.filter((w) => !FILLER.has(w));
  const picked = (content.length ? content : tokens).slice(0, 2);
  if (picked.length === 0) {
    const fallback = raw.split(/\s+/).slice(0, 2);
    return titleCase(fallback) || 'Variants';
  }
  return titleCase(picked);
}
